"""Build the two Phase 2.1 PDFs from reviewed, implementation-specific text."""
from pathlib import Path
from html import escape
import json
import re
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Image, Table, TableStyle, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'output' / 'phase2_1'
SHOTS = OUT / 'screenshots'
OUT.mkdir(parents=True, exist_ok=True)
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyCopy', fontName='Times-Roman', fontSize=12, leading=14, spaceAfter=10))
styles.add(ParagraphStyle(name='TaskCopy', fontName='Times-Roman', fontSize=12, leading=14, spaceAfter=10, leftIndent=14, bulletIndent=0, bulletFontName='Times-Roman', bulletFontSize=12))
styles.add(ParagraphStyle(name='SectionTitle', fontName='Times-Bold', fontSize=17, leading=20, spaceAfter=14))
styles.add(ParagraphStyle(name='SubTitle', fontName='Times-Bold', fontSize=13, leading=16, spaceBefore=5, spaceAfter=8))
styles.add(ParagraphStyle(name='CaptionCopy', fontName='Times-Roman', fontSize=10, leading=12, spaceAfter=10))
styles.add(ParagraphStyle(name='DocTitle', fontName='Times-Bold', fontSize=22, leading=26, spaceAfter=16))
md = []
def para(text, style='BodyCopy'):
    if style == 'BodyCopy' and re.match(r'^[DMS]\d - ', text):
        return Paragraph(escape(text), styles['TaskCopy'], bulletText='-')
    return Paragraph(escape(text), styles[style])
def page(title, paragraphs, first=False):
    md.extend(['# ' + title, ''] + [(' - ' if re.match(r'^[DMS]\d - ', p) else '') + p + '\n' for p in paragraphs])
    return [para(title, 'DocTitle' if first else 'SectionTitle')] + [para(p) for p in paragraphs]
def footer(canvas, doc):
    canvas.setStrokeColor(colors.HexColor('#D1D5DB'))
    canvas.line(54, 44, 558, 44)
    canvas.setFont('Times-Roman', 9)
    canvas.setFillColor(colors.HexColor('#374151'))
    canvas.drawString(54, 31, 'Kitchen Kompanion | Phase 2.1 | November 4, 2026')
    canvas.drawRightString(558, 31, str(doc.page))
def build(name, story):
    SimpleDocTemplate(str(OUT/name), pagesize=(612,792), rightMargin=54, leftMargin=54, topMargin=48, bottomMargin=58, title=name.replace('_',' ').removesuffix('.pdf'), author='Kitchen Kompanion project').build(story, onFirstPage=footer, onLaterPages=footer)

