def screenshot_page(title, entries, wide=False):
    result=[PageBreak(), para(title,'SectionTitle')]
    if wide:
        name, caption=entries[0]
        result += [Image(str(SHOTS/name), width=368, height=552), Spacer(1,12),para(caption,'CaptionCopy')]
    else:
        cells=[]
        for name, caption in entries:
            cells.append([Image(str(SHOTS/name),width=236,height=354),Spacer(1,10),para(caption,'CaptionCopy')])
        table=Table([cells],colWidths=[252]*len(cells),hAlign='LEFT')
        table.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),12)]))
        result.append(table)
    return result
